async function run() {
  const page = figma.getNodeById("0:1");
  if (!page) {
    return "Page 0:1 not found";
  }

  // Find all text nodes on the page to read instructions
  const textNodes = page.findAll(n => n.type === "TEXT");
  const texts = textNodes.map(n => n.name + ": " + n.characters);
  return texts.slice(0, 50).join("\n\n");
}
