(async () => {
  const page = figma.getNodeById("0:1");
  if (!page) return "Page 0:1 not found";
  const texts = [];
  function traverse(node) {
    if (node.type === "TEXT") {
      texts.push(`${node.name}: ${node.characters}`);
    }
    if ("children" in node) {
      for (const child of node.children) {
        traverse(child);
      }
    }
  }
  traverse(page);
  return texts.join("\n\n");
})()

