async function run() {
  try {
    // Let's copy the function and call it, catching any errors
    const workspace = figma.getNodeById("3:2");
    if (!workspace) return "Workspace page 3:2 not found";

    // Test if we can load fonts first
    await figma.loadFontAsync({ family: "Poppins", style: "Regular" });
    await figma.loadFontAsync({ family: "Poppins", style: "Medium" });
    await figma.loadFontAsync({ family: "Poppins", style: "Semi Bold" });
    await figma.loadFontAsync({ family: "Poppins", style: "Bold" });

    return "Fonts loaded successfully!";
  } catch (e) {
    return "ERROR: " + e.message + "\nStack: " + e.stack;
  }
}
run();

