return await (async () => {
  try {
    const workspace = figma.getNodeById("3:2");
    await figma.setCurrentPageAsync(workspace);

    // Load fonts
    await Promise.all([
      figma.loadFontAsync({ family: "Poppins", style: "Regular" }),
      figma.loadFontAsync({ family: "Poppins", style: "Medium" }),
      figma.loadFontAsync({ family: "Poppins", style: "Semi Bold" }),
      figma.loadFontAsync({ family: "Poppins", style: "Bold" })
    ]);

    // Inspect Text Field children and Button children from 02 · Components
    const compPage = figma.getNodeById("1:3");
    const mediaPage = figma.getNodeById("1:4");
    const refBtn = compPage.findOne(n => n.name === "Button" && n.type === "COMPONENT");
    const refField = compPage.findOne(n => n.name === "Text Field" && n.type === "COMPONENT");

    const btnDetails = refBtn.findAll(n => true).map(n => ({ id: n.id, name: n.name, type: n.type, chars: n.type === "TEXT" ? n.characters : null }));
    const fieldDetails = refField.findAll(n => true).map(n => ({ id: n.id, name: n.name, type: n.type, chars: n.type === "TEXT" ? n.characters : null }));

    return JSON.stringify({ btnDetails, fieldDetails });
  } catch (e) {
    return "ERROR: " + e.message;
  }
})()

return await (async () => {
  try {
    const workspace = figma.getNodeById("3:2");

    // Load Poppins font
    await Promise.all([
      figma.loadFontAsync({ family: "Poppins", style: "Regular" }),
      figma.loadFontAsync({ family: "Poppins", style: "Medium" }),
      figma.loadFontAsync({ family: "Poppins", style: "Semi Bold" }),
      figma.loadFontAsync({ family: "Poppins", style: "Bold" })
    ]);

    // 1. Fix Log In screen (Frame 3) Text Fields
    const logInFrame = workspace.findOne(n => n.name === "03_Log_In" && n.type === "FRAME");
    if (logInFrame) {
      // Find all Text Field instances inside Frame 3
      const fields = logInFrame.findAll(n => n.name === "Text Field" && n.type === "INSTANCE");

      // Let's print how many we found and update them
      if (fields.length >= 2) {
        // The first field is email field (at y = 260)
        // The second field is password field (at y = 330)
        const emailField = fields.find(f => f.y === 260);
        const passField = fields.find(f => f.y === 330);

        if (emailField) {
          const tNode = emailField.findOne(n => n.type === "TEXT");
          if (tNode) tNode.characters = "dani@example.com";
        }

        if (passField) {
          const tNode = passField.findOne(n => n.type === "TEXT");
          if (tNode) tNode.characters = "••••••••";
        }
      }
    }

    return "SUCCESS: Cleaned up and updated text fields on Log In screen!";
  } catch (e) {
    return "ERROR: " + e.message + "\nStack: " + e.stack;
  }
})()
